const RELIC_TEXT = {
  trident: { name: "Poseidon's Trident", body: "In Greek myths, Poseidon, god of the sea, carried a three-pronged spear called a trident. Plato wrote that Poseidon founded Atlantis and ruled it. Real fishermen around the Mediterranean used tridents to spear fish." },
  lawTablet: { name: "The Orichalcum Tablet", body: "Plato wrote that the laws of Atlantis were carved on a pillar of orichalcum, a metal that 'flashed like fire'. Nobody knows what orichalcum really was: maybe brass, made from copper and zinc. In this game, ancient metal is our orichalcum." },
  seahorse: { name: "The Golden Hippocamp", body: "A hippocamp is a sea-horse from Greek myths: half horse, half fish, pulling Poseidon's chariot through the waves. Plato described a golden statue of Poseidon driving six winged horses. Real seahorses are tiny fish, and it's the fathers who carry the babies!" },
};
