// New places (October 2026): Jerusalem, Carthage, the Forbidden City and the Three Kingdoms of China.
Object.assign(SITE_TEXT, {
  jerusalem: { name: 'Jerusalem', place: 'Judea', date: 'Second Temple, c. 516 BCE – 70 CE', fact: 'The Second Temple was built about 516 BCE, after the Jewish people came home from exile in Babylon. King Herod rebuilt it in grand style from about 20 BCE. The Romans destroyed it in 70 CE. Part of the wall around its great platform still stands: the Western Wall.', more: 'Herod made the Temple Mount the biggest platform of its kind in the ancient world. One stone in the Western Wall is about 13 metres long. Three times a year, at Passover, Shavuot and Sukkot, crowds of pilgrims came from far away. Only the High Priest could enter the innermost room, the Holy of Holies, and only once a year, on Yom Kippur.', hello: 'Shalom! That means peace, and we say it for hello.', guide: 'Miriam', title: 'Daughter of a Temple Builder' },
  carthage: { name: 'Carthage', place: 'North Africa (Tunisia)', date: 'c. 814 – 146 BCE', fact: 'Carthage was founded by Phoenician sailors from the city of Tyre, traditionally in 814 BCE. It grew into the greatest sea power in the western Mediterranean. Its round war harbour, the cothon, had sheds for about 220 warships. Rome destroyed the city in 146 BCE.', more: 'Carthage fought three long wars against Rome, called the Punic Wars. In 218 BCE its general Hannibal marched an army, with elephants, over the Alps into Italy. Carthaginians were famous traders: they sold purple cloth, made with dye from sea snails, all around the sea.', hello: 'Welcome to Qart-hadasht, the New City!', guide: 'Hanno', title: 'Harbour Master' },
  forbiddenCity: { name: 'The Forbidden City', place: 'Beijing, China', date: 'Built 1406–1420 CE', fact: 'The Forbidden City was the palace of the emperors of China. The Yongle Emperor of the Ming dynasty built it between 1406 and 1420. About 980 buildings stand inside its red walls and moat. Twenty-four emperors lived here, until the last one gave up the throne in 1912.', more: 'Only the emperor could use yellow roof tiles, so the palace roofs shine gold. The biggest hall, the Hall of Supreme Harmony, stands on three tiers of white marble. Ordinary people could not come in without permission, so it was called "forbidden". Today it is the Palace Museum, and millions of people visit every year.', hello: 'Welcome to the Northern Capital!', guide: 'Mei', title: 'Palace Painter' },
  wei: { name: 'Wei (Luoyang)', place: 'Northern China', date: 'Three Kingdoms, 220–266 CE', fact: 'After the Han dynasty ended in 220 CE, China split into Three Kingdoms: Wei, Shu and Wu. Wei held the rich north. Its first emperor, Cao Pi, was the son of the famous general Cao Cao, and its capital was Luoyang.', more: 'Wei was the biggest and strongest of the three kingdoms. Cao Cao set up farms run by soldiers, called tuntian, so his armies always had grain. The kingdom of Jin, which took over from Wei, finally reunited China in 280 CE. Hundreds of years later, these wars became a famous book: Romance of the Three Kingdoms.', hello: 'Welcome to Luoyang, capital of Wei!', guide: 'Jing', title: 'Court Scribe' },
  shu: { name: 'Shu (Chengdu)', place: 'Sichuan, China', date: 'Three Kingdoms, 221–263 CE', fact: 'Shu was the kingdom of Liu Bei, who said he was the true heir of the Han emperors. He ruled from Chengdu, in a fertile basin ringed by mountains. His wise chancellor, Zhuge Liang, is one of the most famous people in Chinese history.', more: 'Shu was rich from silk brocade, salt and tea. Its fields were watered by Dujiangyan, a clever river system built around 256 BCE that still works today! Shu was the smallest of the Three Kingdoms, and Wei conquered it in 263 CE.', hello: 'Welcome to Chengdu, the Brocade City!', guide: 'Yue', title: 'Silk Merchant' },
  wu: { name: 'Wu (Jianye)', place: 'Southern China', date: 'Three Kingdoms, 222–280 CE', fact: 'Wu was the kingdom of Sun Quan, in the south along the great Yangtze River. Its capital, Jianye, is the city of Nanjing today. Wu had the strongest navy of the Three Kingdoms.', more: 'In 208 CE, at the Battle of Red Cliffs, the armies of Sun Quan and Liu Bei beat Cao Cao\'s much bigger fleet, using ships set on fire. Wu sent sailors and envoys as far as Southeast Asia. It was the last of the Three Kingdoms to fall, in 280 CE.', hello: 'Welcome to Jianye, on the Long River!', guide: 'Ling', title: 'Shipwright' },
});
Object.assign(CITY_INFO, {
  jerusalem: { population: 70000, guess: true, when: 'around 30 CE', style: 'judean', life: 'Our houses are built of the pale local stone, with flat roofs where we dry figs and sleep on hot nights. At festival time the city fills with pilgrims, and families squeeze guests into every room.', names: ['Miriam', 'Yosef', 'Shimon', 'Hannah', 'Eleazar', 'Salome', 'Yehudah', 'Shoshanah', 'Yohanan', 'Marta', 'Levi', 'Rivkah'], jobs: [['stonemason', 'I cut stone for the Temple Mount. Some blocks are as long as a bus, and they stay up by their own weight, with no mortar.'], ['potter', 'I make stone and clay jars. Stone jars are special here, because the law says stone cannot become unclean.'], ['olive farmer', 'Our olives grow on the Mount of Olives. The purest oil burns in the Temple lamps.'], ['scribe', 'I copy the holy books with a reed pen on parchment, one letter at a time.']] },
  carthage: { population: 200000, guess: true, when: 'around 150 BCE', style: 'punic', life: 'Our houses stand close together, some six floors high, and they are plastered white. Many have a cistern under the floor to catch rainwater, and a little bathtub!', names: ['Hanno', 'Elissa', 'Himilco', 'Sophonisba', 'Bomilcar', 'Arishat', 'Mago', 'Batbaal', 'Hasdrubal', 'Tanitbaal'], jobs: [['purple dyer', 'I crush murex sea snails to make purple dye. It takes thousands of snails to dye one robe!'], ['shipwright', 'I build warships. Every piece is marked with a letter, so the ship goes together quickly, like a kit.'], ['sailor', 'Our sailors know the whole sea. Some have sailed out past the Pillars of Hercules, into the ocean beyond.'], ['olive farmer', 'The farms around Carthage are famous. A Carthaginian named Mago wrote a book on farming that even the Romans copied.']] },
  forbiddenCity: { population: 600000, when: 'around 1500 CE', style: 'chinese', life: 'We live in courtyard houses called siheyuan, along narrow lanes called hutongs. In winter we sleep on a kang, a brick bed with a fire underneath to keep it warm.', names: ['Mei', 'Wei', 'Lan', 'Jun', 'Hua', 'Ming', 'Xiu', 'Bao', 'Fang', 'Qiang', 'Ling', 'Zhen'], jobs: [['carpenter', 'I build palace halls from huge timbers. We fit the beams together with wooden joints, without nails.'], ['beam painter', 'I paint the beams under the roofs with dragons, flowers and clouds. The paint protects the wood from the weather too.'], ['gardener', 'I look after the Imperial Garden, with its old cypress trees and strange rocks from Lake Tai.'], ['shopkeeper', 'I sell blue-and-white porcelain from Jingdezhen. People all over the world want to buy it.']] },
  wei: { population: 100000, guess: true, when: 'around 230 CE', style: 'chinese', life: 'Luoyang was burned in a war in 190, so we are building it again. Our houses have walls of rammed earth, pounded hard between wooden boards, and tiled roofs.', names: ['Jing', 'Pi', 'Zhen', 'Ling', 'Rui', 'Hua', 'Yan', 'Hu', 'Bo', 'Xiu'], jobs: [['millet farmer', 'Millet is the grain of the north. Cao Cao set up soldier farms, so the army grows its own food.'], ['paper maker', 'I make paper from mulberry bark, hemp and old rags. Paper is much lighter than the bamboo strips people wrote on before.'], ['blacksmith', 'Our iron is melted and poured into moulds. A water wheel pumps the bellows to make the fire extra hot.']] },
  shu: { population: 100000, guess: true, when: 'around 230 CE', style: 'chinese', life: 'Our basin is warm and misty, and the land is so rich people call it the Land of Abundance. Houses are wood and tile, and there are tea houses on every street.', names: ['Yue', 'Tao', 'Wei', 'Lan', 'Ping', 'Xing', 'Qian', 'Hong', 'Jian', 'Yun'], jobs: [['silk weaver', 'I weave Shu brocade, silk with patterns woven right in. The chancellor says brocade pays for the whole army!'], ['salt worker', 'We drill deep wells to bring up salty water, then boil it until only salt is left.'], ['tea farmer', 'We pick tea leaves on the misty hills. People here have been drinking tea for hundreds of years.']] },
  wu: { population: 100000, guess: true, when: 'around 230 CE', style: 'chinese', life: 'We live by the water. Boats are everywhere, and people say this is the land of fish and rice.', names: ['Ling', 'Quan', 'Shang', 'Lian', 'Ce', 'Xiao', 'Gong', 'Mei', 'Tai', 'Ying'], jobs: [['shipwright', 'I build tower ships for the navy, with several decks, like floating castles.'], ['rice farmer', 'The south is warm and wet, perfect for rice in flooded paddy fields.'], ['fisher', 'The Long River and its lakes are full of fish, and river dolphins too.']] },
});

// Olympia (October 24): the sanctuary of Zeus where the Olympic Games began.
Object.assign(SITE_TEXT, {
  olympia: { name: 'Olympia', place: 'Greece', date: 'Olympic Games from 776 BCE', fact: 'Olympia was a sanctuary of Zeus, the king of the Greek gods. Traditionally, the first Olympic Games were held here in 776 BCE, and they took place every four years for more than a thousand years. Inside the Temple of Zeus sat a giant statue of him made of gold and ivory: one of the Seven Wonders of the Ancient World.', more: 'Athletes came from all over the Greek world. They ran races, wrestled, boxed, threw the discus and javelin, and raced chariots. Winners got no gold medals: they were crowned with a wreath cut from the sacred olive tree, and their home cities treated them as heroes. During the Games, a sacred truce let people travel here safely, even when their cities were at war.', hello: 'Chaire! Welcome to Olympia, home of the Games!', guide: 'Kyniska', title: 'Chariot Owner and Olympic Champion' },
});
Object.assign(CITY_INFO, {
  olympia: { population: 40000, guess: true, when: 'during the Games, around 400 BCE', style: 'greek', life: 'Most of the year Olympia is quiet: priests, guards and a few workers live here. But every four years, crowds of visitors arrive for the Games and camp in tents all around the sanctuary!', names: ['Kyniska', 'Milo', 'Leonidas', 'Theagenes', 'Melankomas', 'Diagoras', 'Phidias', 'Eudoxos', 'Damaretos', 'Chionis'], jobs: [['athlete', 'I train every day in the palaestra and the gymnasium. Before the Games, athletes had to train for a whole month at nearby Elis, watched by the judges.'], ['judge', 'I am one of the Hellanodikai, the judges of the Greeks. We wear purple robes, and we fine anyone who cheats.'], ['sculptor', 'I make statues of the winners. A champion who wins three times may have a statue that looks just like him!'], ['olive farmer', 'I look after the sacred olive tree. A boy whose parents are both alive cuts the winners\' wreaths with a golden sickle.']] },
});
